//! Oracle tests: each row of `oracle_data::VECTORS` is run through the port, and the output must be
//! the line that Wine's C oracle printed for it (`oracle_data::ORACLE`). The rows are generated by
//! `target/canon/nsi/build.sh`, and the output formats are those of `target/canon/nsi/harness.c`.
//! Row modes: `GP`/`GPE` get-parameter, `WGP` its input size, `GA`/`GAE` get-all, `WGA` its sizes,
//! `EN`/`ENE` enumerate, `WEN` its reply size, `AL` allocate-and-get-table, `WAL` its bytes, and
//! `CN` cancel. Device replies are scripted as `status:count` tokens after the row arguments.

use super::*;
use crate::oracle_data::{ORACLE, VECTORS};

type Row = fn(&str, &[&str]) -> String;

const MODES: [(&str, Row); 12] = [
    ("GP", get_parameter_row),
    ("GPE", get_parameter_row),
    ("WGP", wgp_row),
    ("GA", get_all_row),
    ("GAE", get_all_row),
    ("WGA", wga_row),
    ("EN", enumerate_row),
    ("ENE", enumerate_row),
    ("WEN", wen_row),
    ("AL", allocate_row),
    ("WAL", wal_row),
    ("CN", cancel_row),
];

/// Answers device calls from a script of `(status, count)` replies. Calls past the script get `(87, 0)`.
struct Device {
    script: Vec<(u32, u32)>,
    pos: usize,
    /// `(input, output size)` of every call, as the harness records them.
    calls: Vec<(u32, u32)>,
}

impl Device {
    fn new(script: &[&str]) -> Self {
        let script = script
            .iter()
            .map(|token| {
                let (status, count) = token.split_once(':').expect("status:count");
                (num(status), num(count))
            })
            .collect();
        Self {
            script,
            pos: 0,
            calls: Vec::new(),
        }
    }

    /// Records a call, then answers it. As in the harness, status 0 or 234 fills the output with
    /// `out[i] = i`. An enumeration starts with its count as a DWORD, and bytes from index 4 are filled.
    fn call(&mut self, input: u32, enumerate: bool, out: &mut [u8]) -> (u32, u32) {
        self.calls.push((input, out.len() as u32));
        let (status, count) = self.script.get(self.pos).copied().unwrap_or((87, 0));
        self.pos += 1;
        if status == 0 || status == 234 {
            let start = if enumerate {
                out[..4].copy_from_slice(&count.to_le_bytes());
                4
            } else {
                0
            };
            for (i, byte) in out.iter_mut().enumerate().skip(start) {
                *byte = i as u8;
            }
        }
        (status, count)
    }

    fn first(&self) -> (u32, u32) {
        self.calls.first().copied().unwrap_or_default()
    }
}

fn num(token: &str) -> u32 {
    token.parse().expect("u32 argument")
}

fn block_sizes(args: &[&str]) -> BlockSizes {
    BlockSizes {
        key: num(args[0]),
        rw: num(args[1]),
        dynamic: num(args[2]),
        stat: num(args[3]),
    }
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn or_dash<T: ToString>(value: Option<T>) -> String {
    value.map_or_else(|| "-".to_string(), |value| value.to_string())
}

fn bytes_field(bytes: Option<[u32; 4]>) -> String {
    bytes.map_or_else(
        || "-".to_string(),
        |bytes| bytes.map(|n| n.to_string()).join(","),
    )
}

fn copy_segment(out: &[u8], segment: Segment, dst: &mut [u8]) {
    let start = segment.offset as usize;
    let len = segment.len as usize;
    dst[..len].copy_from_slice(&out[start..start + len]);
}

fn get_parameter_row(id: &str, args: &[&str]) -> String {
    let mut device = Device::new(&args[2..]);
    let mut data = vec![0xEE; num(args[1]) as usize];
    let err = get_parameter(num(args[0]), |in_size| {
        device.call(in_size, false, &mut data).0
    });
    format!("{id} err={err} insz={} d={}", device.first().0, hex(&data))
}

fn wgp_row(id: &str, args: &[&str]) -> String {
    format!(
        "{id} in={}",
        or_dash(get_parameter_input_size(num(args[0])))
    )
}

fn get_all_row(id: &str, args: &[&str]) -> String {
    let (key, rw, dynamic, stat) = (num(args[0]), num(args[1]), num(args[2]), num(args[3]));
    let mut device = Device::new(&args[4..]);
    let mut out = Vec::new();
    let mut rw_data = vec![0xEE; rw as usize];
    let mut dynamic_data = vec![0xEE; dynamic as usize];
    let mut static_data = vec![0xEE; stat as usize];
    let result = get_all_parameters(key, rw, dynamic, stat, |in_size, out_size| {
        out = vec![0; out_size as usize];
        device.call(in_size, false, &mut out).0
    });
    let err = match result {
        Ok(segments) => {
            copy_segment(&out, segments[0], &mut rw_data);
            copy_segment(&out, segments[1], &mut dynamic_data);
            copy_segment(&out, segments[2], &mut static_data);
            ERROR_SUCCESS
        }
        Err(status) => status,
    };
    let (in_size, out_size) = device.first();
    format!(
        "{id} err={err} insz={in_size} outsz={out_size} r={} d={} s={}",
        hex(&rw_data),
        hex(&dynamic_data),
        hex(&static_data)
    )
}

fn wga_row(id: &str, args: &[&str]) -> String {
    let in_size = get_all_parameters_input_size(num(args[0]));
    let out_size = get_all_parameters_out_size(num(args[1]), num(args[2]), num(args[3]));
    format!("{id} in={} out={}", or_dash(in_size), or_dash(out_size))
}

fn enumerate_row(id: &str, args: &[&str]) -> String {
    let requested = num(args[0]);
    let sizes = block_sizes(&args[1..5]);
    let mut device = Device::new(&args[5..]);
    let mut out = Vec::new();
    let result = enumerate_all_parameters(sizes, requested, |count, out_size| {
        out = vec![0; out_size as usize];
        device.call(count, true, &mut out)
    });
    let mut key = vec![0xEE; (sizes.key * requested) as usize];
    let mut rw_data = vec![0xEE; (sizes.rw * requested) as usize];
    let mut dynamic_data = vec![0xEE; (sizes.dynamic * requested) as usize];
    let mut static_data = vec![0xEE; (sizes.stat * requested) as usize];
    if let Some(blocks) = result.blocks {
        copy_segment(&out, blocks[0], &mut key);
        copy_segment(&out, blocks[1], &mut rw_data);
        copy_segment(&out, blocks[2], &mut dynamic_data);
        copy_segment(&out, blocks[3], &mut static_data);
    }
    let (_, out_size) = device.first();
    format!(
        "{id} err={} count={} outsz={out_size} k={} r={} d={} s={}",
        result.status,
        result.count,
        hex(&key),
        hex(&rw_data),
        hex(&dynamic_data),
        hex(&static_data)
    )
}

fn wen_row(id: &str, args: &[&str]) -> String {
    format!(
        "{id} out={}",
        or_dash(enumerate_out_size(block_sizes(&args[1..5]), num(args[0])))
    )
}

fn allocate_row(id: &str, args: &[&str]) -> String {
    let sizes = block_sizes(&args[..4]);
    let mut device = Device::new(&args[4..]);
    let result = allocate_and_get_table(sizes, |block_sizes, count| {
        enumerate_all_parameters(block_sizes, count, |requested, out_size| {
            let mut out = vec![0; out_size as usize];
            device.call(requested, true, &mut out)
        })
    });
    let calls: Vec<String> = device
        .calls
        .iter()
        .map(|(input, out)| format!("{input}:{out}"))
        .collect();
    let calls = calls.join(";");
    match result {
        Ok(table) => format!(
            "{id} err=0 count={} bytes={} calls={calls}",
            table.count,
            bytes_field(Some(table.bytes))
        ),
        Err(err) => format!("{id} err={err} count=- bytes=- calls={calls}"),
    }
}

fn wal_row(id: &str, args: &[&str]) -> String {
    format!(
        "{id} bytes={}",
        bytes_field(table_buffer_bytes(block_sizes(&args[..4]), num(args[4])))
    )
}

fn cancel_row(id: &str, args: &[&str]) -> String {
    let status = num(args[1]);
    let err = cancel_change_notification(num(args[0]) != 0, || match status {
        0 => Ok(()),
        error => Err(error),
    });
    format!("{id} err={err}")
}

#[test]
fn oracle_rows_match_wine() {
    let vectors: Vec<&str> = VECTORS.lines().filter(|line| !line.is_empty()).collect();
    let oracle: Vec<&str> = ORACLE.lines().filter(|line| !line.is_empty()).collect();
    assert_eq!(vectors.len(), oracle.len());
    assert_eq!(vectors.len(), 106);
    for (vector, expected) in vectors.into_iter().zip(oracle) {
        let mut fields = vector.split_whitespace();
        let mode = fields.next().expect("mode");
        let id = fields.next().expect("id");
        let args: Vec<&str> = fields.collect();
        let (_, row) = MODES
            .iter()
            .find(|(name, _)| *name == mode)
            .expect("known mode");
        assert_eq!(row(id, &args), expected, "{vector}");
    }
}
